#!/usr/bin/env python3"""Скрипт для создания пользователя с известным паролем"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from core.database import enginefrom models.user import Userfrom sqlmodel import Session, selectfrom core.auth import get_password_hashdef create_user():    """Создает пользователя с паролем 'password'"""    with Session(engine) as session:        # Удаляем существующего пользователя test        existing_user = session.exec(select(User).where(User.username == "test")).first()        if existing_user:            session.delete(existing_user)            session.commit()            print("Удален существующий пользователь 'test'")                # Создаем нового пользователя        user = User(            username="test",            email="test@example.com",            hashed_password=get_password_hash("password"),            is_active=True        )                session.add(user)        session.commit()        session.refresh(user)                print(f"Создан пользователь: {user.username} (ID: {user.id})")        print("Пароль: password")        return userif __name__ == "__main__":    create_user()